fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    if s.len() < 2 {
        return None;
    }
    // max1 = largest seen so far
    // max2 = second-largest (in sorted order, the element at s.len()-2)
    let mut max1 = i8::MIN;
    let mut max2 = i8::MIN;

    for &x in s.iter() {
        if x >= max1 {
            // x becomes the new largest, and the old largest
            // is demoted to second‐largest
            max2 = max1;
            max1 = x;
        } else if x > max2 {
            // x sits between max1 and max2
            max2 = x;
        }
    }

    Some(max2)
}

